    Action.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'AttributeName', traits: {"smithy.api#documentation" => "<p>The related time series that you are modifying. This value is case insensitive.</p>", "smithy.api#required" => {}}))
    Action.add_member(:operation, Smithy::Schema::Shapes::ShapeRef.new(shape: Operation, location_name: 'Operation', traits: {"smithy.api#documentation" => "<p>The operation that is applied to the provided attribute. Operations include:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ADD</code> - adds <code>Value</code> to all rows of <code>AttributeName</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>SUBTRACT</code> - subtracts <code>Value</code> from all rows of <code>AttributeName</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>MULTIPLY</code> - multiplies all rows of <code>AttributeName</code> by <code>Value</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>DIVIDE</code> - divides all rows of <code>AttributeName</code> by <code>Value</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    Action.add_member(:value, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'Value', traits: {"smithy.api#documentation" => "<p>The value that is applied for the chosen <code>Operation</code>.</p>", "smithy.api#required" => {}}))
    Action.type = Types::Action
    AdditionalDataset.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the additional dataset. Valid names: <code>\"holiday\"</code> and\n                <code>\"weather\"</code>.</p>", "smithy.api#required" => {}}))
    AdditionalDataset.add_member(:configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: Configuration, location_name: 'Configuration', traits: {"smithy.api#documentation" => "<p>\n            <b>Weather Index</b>\n         </p>\n         <p>To enable the Weather Index, do not specify a value for\n            <code>Configuration</code>.</p>\n         <p>\n            <b>Holidays</b>\n         </p>\n         <p>\n            <b>Holidays</b>\n         </p>\n         <p>To enable Holidays, set <code>CountryCode</code> to one of the following two-letter\n            country codes:</p>\n         <ul>\n            <li>\n               <p>\"AL\" - ALBANIA</p>\n            </li>\n            <li>\n               <p>\"AR\" - ARGENTINA</p>\n            </li>\n            <li>\n               <p>\"AT\" - AUSTRIA</p>\n            </li>\n            <li>\n               <p>\"AU\" - AUSTRALIA</p>\n            </li>\n            <li>\n               <p>\"BA\" - BOSNIA HERZEGOVINA</p>\n            </li>\n            <li>\n               <p>\"BE\" - BELGIUM</p>\n            </li>\n            <li>\n               <p>\"BG\" - BULGARIA</p>\n            </li>\n            <li>\n               <p>\"BO\" - BOLIVIA</p>\n            </li>\n            <li>\n               <p>\"BR\" - BRAZIL</p>\n            </li>\n            <li>\n               <p>\"BY\" - BELARUS</p>\n            </li>\n            <li>\n               <p>\"CA\" - CANADA</p>\n            </li>\n            <li>\n               <p>\"CL\" - CHILE</p>\n            </li>\n            <li>\n               <p>\"CO\" - COLOMBIA</p>\n            </li>\n            <li>\n               <p>\"CR\" - COSTA RICA</p>\n            </li>\n            <li>\n               <p>\"HR\" - CROATIA</p>\n            </li>\n            <li>\n               <p>\"CZ\" - CZECH REPUBLIC</p>\n            </li>\n            <li>\n               <p>\"DK\" - DENMARK</p>\n            </li>\n            <li>\n               <p>\"EC\" - ECUADOR</p>\n            </li>\n            <li>\n               <p>\"EE\" - ESTONIA</p>\n            </li>\n            <li>\n               <p>\"ET\" - ETHIOPIA</p>\n            </li>\n            <li>\n               <p>\"FI\" - FINLAND</p>\n            </li>\n            <li>\n               <p>\"FR\" - FRANCE</p>\n            </li>\n            <li>\n               <p>\"DE\" - GERMANY</p>\n            </li>\n            <li>\n               <p>\"GR\" - GREECE</p>\n            </li>\n            <li>\n               <p>\"HU\" - HUNGARY</p>\n            </li>\n            <li>\n               <p>\"IS\" - ICELAND</p>\n            </li>\n            <li>\n               <p>\"IN\" - INDIA</p>\n            </li>\n            <li>\n               <p>\"IE\" - IRELAND</p>\n            </li>\n            <li>\n               <p>\"IT\" - ITALY</p>\n            </li>\n            <li>\n               <p>\"JP\" - JAPAN</p>\n            </li>\n            <li>\n               <p>\"KZ\" - KAZAKHSTAN</p>\n            </li>\n            <li>\n               <p>\"KR\" - KOREA</p>\n            </li>\n            <li>\n               <p>\"LV\" - LATVIA</p>\n            </li>\n            <li>\n               <p>\"LI\" - LIECHTENSTEIN</p>\n            </li>\n            <li>\n               <p>\"LT\" - LITHUANIA</p>\n            </li>\n            <li>\n               <p>\"LU\" - LUXEMBOURG</p>\n            </li>\n            <li>\n               <p>\"MK\" - MACEDONIA</p>\n            </li>\n            <li>\n               <p>\"MT\" - MALTA</p>\n            </li>\n            <li>\n               <p>\"MX\" - MEXICO</p>\n            </li>\n            <li>\n               <p>\"MD\" - MOLDOVA</p>\n            </li>\n            <li>\n               <p>\"ME\" - MONTENEGRO</p>\n            </li>\n            <li>\n               <p>\"NL\" - NETHERLANDS</p>\n            </li>\n            <li>\n               <p>\"NZ\" - NEW ZEALAND</p>\n            </li>\n            <li>\n               <p>\"NI\" - NICARAGUA</p>\n            </li>\n            <li>\n               <p>\"NG\" - NIGERIA</p>\n            </li>\n            <li>\n               <p>\"NO\" - NORWAY</p>\n            </li>\n            <li>\n               <p>\"PA\" - PANAMA</p>\n            </li>\n            <li>\n               <p>\"PY\" - PARAGUAY</p>\n            </li>\n            <li>\n               <p>\"PE\" - PERU</p>\n            </li>\n            <li>\n               <p>\"PL\" - POLAND</p>\n            </li>\n            <li>\n               <p>\"PT\" - PORTUGAL</p>\n            </li>\n            <li>\n               <p>\"RO\" - ROMANIA</p>\n            </li>\n            <li>\n               <p>\"RU\" - RUSSIA</p>\n            </li>\n            <li>\n               <p>\"RS\" - SERBIA</p>\n            </li>\n            <li>\n               <p>\"SK\" - SLOVAKIA</p>\n            </li>\n            <li>\n               <p>\"SI\" - SLOVENIA</p>\n            </li>\n            <li>\n               <p>\"ZA\" - SOUTH AFRICA</p>\n            </li>\n            <li>\n               <p>\"ES\" - SPAIN</p>\n            </li>\n            <li>\n               <p>\"SE\" - SWEDEN</p>\n            </li>\n            <li>\n               <p>\"CH\" - SWITZERLAND</p>\n            </li>\n            <li>\n               <p>\"UA\" - UKRAINE</p>\n            </li>\n            <li>\n               <p>\"AE\" - UNITED ARAB EMIRATES</p>\n            </li>\n            <li>\n               <p>\"US\" - UNITED STATES</p>\n            </li>\n            <li>\n               <p>\"UK\" - UNITED KINGDOM</p>\n            </li>\n            <li>\n               <p>\"UY\" - URUGUAY</p>\n            </li>\n            <li>\n               <p>\"VE\" - VENEZUELA</p>\n            </li>\n         </ul>"}))
