    Baseline.add_member(:predictor_baseline, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictorBaseline, location_name: 'PredictorBaseline', traits: {"smithy.api#documentation" => "<p>The initial <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/metrics.html\">accuracy metrics</a> for the predictor you are monitoring. Use these metrics as a baseline for comparison purposes as you\n         use your predictor and the metrics change.</p>"}))
