    ContinuousParameterRange.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the hyperparameter to tune.</p>", "smithy.api#required" => {}}))
    ContinuousParameterRange.add_member(:max_value, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'MaxValue', traits: {"smithy.api#documentation" => "<p>The maximum tunable value of the hyperparameter.</p>", "smithy.api#required" => {}}))
    ContinuousParameterRange.add_member(:min_value, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'MinValue', traits: {"smithy.api#documentation" => "<p>The minimum tunable value of the hyperparameter.</p>", "smithy.api#required" => {}}))
    ContinuousParameterRange.add_member(:scaling_type, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingType, location_name: 'ScalingType', traits: {"smithy.api#documentation" => "<p>The scale that hyperparameter tuning uses to search the hyperparameter range.\n      Valid values:</p>\n         <dl>\n            <dt>Auto</dt>\n            <dd>\n               <p>Amazon Forecast hyperparameter tuning chooses the best scale for the hyperparameter.</p>\n            </dd>\n            <dt>Linear</dt>\n            <dd>\n               <p>Hyperparameter tuning searches the values in the hyperparameter range by using a\n            linear scale.</p>\n            </dd>\n            <dt>Logarithmic</dt>\n            <dd>\n               <p>Hyperparameter tuning searches the values in the hyperparameter range by using a\n            logarithmic scale.</p>\n               <p>Logarithmic scaling works only for ranges that have values greater than 0.</p>\n            </dd>\n            <dt>ReverseLogarithmic</dt>\n            <dd>\n               <p>hyperparameter tuning searches the values in the hyperparameter range by using a\n            reverse logarithmic scale.</p>\n               <p>Reverse logarithmic scaling works only for ranges that are entirely within the\n            range 0 <= x < 1.0.</p>\n            </dd>\n         </dl>\n         <p>For information about choosing a hyperparameter scale, see\n      <a href=\"http://docs.aws.amazon.com/sagemaker/latest/dg/automatic-model-tuning-define-ranges.html#scaling-type\">Hyperparameter Scaling</a>.\n      One of the following values:</p>"}))
    ContinuousParameterRange.type = Types::ContinuousParameterRange
