    CreateAutoPredictorRequest.add_member(:predictor_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'PredictorName', traits: {"smithy.api#documentation" => "<p>A unique name for the predictor</p>", "smithy.api#required" => {}}))
    CreateAutoPredictorRequest.add_member(:forecast_horizon, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ForecastHorizon', traits: {"smithy.api#documentation" => "<p>The number of time-steps that the model predicts. The forecast horizon is also called\n            the prediction length.</p>\n         <p>The maximum forecast horizon is the lesser of 500 time-steps or 1/4 of the\n            TARGET_TIME_SERIES dataset length. If you are retraining an existing AutoPredictor, then\n            the maximum forecast horizon is the lesser of 500 time-steps or 1/3 of the\n            TARGET_TIME_SERIES dataset length.</p>\n         <p>If you are upgrading to an AutoPredictor or retraining an existing AutoPredictor, you\n            cannot update the forecast horizon parameter. You can meet this requirement by providing\n            longer time-series in the dataset.</p>"}))
    CreateAutoPredictorRequest.add_member(:forecast_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastTypes, location_name: 'ForecastTypes', traits: {"smithy.api#documentation" => "<p>The forecast types used to train a predictor. You can specify up to five forecast\n            types. Forecast types can be quantiles from 0.01 to 0.99, by increments of 0.01 or\n            higher. You can also specify the mean forecast with <code>mean</code>.</p>"}))
    CreateAutoPredictorRequest.add_member(:forecast_dimensions, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastDimensions, location_name: 'ForecastDimensions', traits: {"smithy.api#documentation" => "<p>An array of dimension (field) names that specify how to group the generated\n            forecast.</p>\n         <p>For example, if you are generating forecasts for item sales across all your stores,\n            and your dataset contains a <code>store_id</code> field, you would specify\n                <code>store_id</code> as a dimension to group sales forecasts for each store.</p>"}))
    CreateAutoPredictorRequest.add_member(:forecast_frequency, Smithy::Schema::Shapes::ShapeRef.new(shape: Frequency, location_name: 'ForecastFrequency', traits: {"smithy.api#documentation" => "<p>The frequency of predictions in a forecast.</p>\n         <p>Valid intervals are an integer followed by Y (Year), M (Month), W (Week), D (Day), H (Hour), and min (Minute). For example,\n        \"1D\" indicates every day and \"15min\" indicates every 15 minutes. You cannot specify a value that would overlap with the next larger frequency. That means, for example, you cannot specify a frequency of 60 minutes, because that is equivalent to 1 hour. The valid values for each frequency are the following:</p>\n         <ul>\n            <li>\n               <p>Minute - 1-59</p>\n            </li>\n            <li>\n               <p>Hour - 1-23</p>\n            </li>\n            <li>\n               <p>Day - 1-6</p>\n            </li>\n            <li>\n               <p>Week - 1-4</p>\n            </li>\n            <li>\n               <p>Month - 1-11</p>\n            </li>\n            <li>\n               <p>Year - 1</p>\n            </li>\n         </ul>\n         <p>Thus, if you want every other week forecasts, specify \"2W\". Or, if you want quarterly forecasts, you specify \"3M\".</p>\n         <p>The frequency must be greater than or equal to the TARGET_TIME_SERIES dataset\n            frequency.</p>\n         <p>When a RELATED_TIME_SERIES dataset is provided, the frequency must be equal to the\n            RELATED_TIME_SERIES dataset frequency.</p>"}))
    CreateAutoPredictorRequest.add_member(:data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DataConfig, location_name: 'DataConfig', traits: {"smithy.api#documentation" => "<p>The data configuration for your dataset group and any additional datasets.</p>"}))
    CreateAutoPredictorRequest.add_member(:encryption_config, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionConfig, location_name: 'EncryptionConfig'))
    CreateAutoPredictorRequest.add_member(:reference_predictor_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'ReferencePredictorArn', traits: {"smithy.api#documentation" => "<p>The ARN of the predictor to retrain or upgrade. This parameter is only used when\n            retraining or upgrading a predictor. When creating a new predictor, do not specify a\n            value for this parameter.</p>\n         <p>When upgrading or retraining a predictor, only specify values for the\n                <code>ReferencePredictorArn</code> and <code>PredictorName</code>. The value for\n                <code>PredictorName</code> must be a unique predictor name.</p>"}))
    CreateAutoPredictorRequest.add_member(:optimization_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: OptimizationMetric, location_name: 'OptimizationMetric', traits: {"smithy.api#documentation" => "<p>The accuracy metric used to optimize the predictor.</p>"}))
    CreateAutoPredictorRequest.add_member(:explain_predictor, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExplainPredictor', traits: {"smithy.api#documentation" => "<p>Create an Explainability resource for the predictor.</p>"}))
    CreateAutoPredictorRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Optional metadata to help you categorize and organize your predictors. Each tag\n            consists of a key and an optional value, both of which you define. Tag keys and values\n            are case sensitive.</p>\n         <p>The following restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>For each resource, each tag key must be unique and each tag key must have one\n                    value.</p>\n            </li>\n            <li>\n               <p>Maximum number of tags per resource: 50.</p>\n            </li>\n            <li>\n               <p>Maximum key length: 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length: 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Accepted characters: all letters and numbers, spaces representable in UTF-8,\n                    and + - = . _ : / @. If your tagging schema is used across other services and\n                    resources, the character restrictions of those services also apply. </p>\n            </li>\n            <li>\n               <p>Key prefixes cannot include any upper or lowercase combination of\n                        <code>aws:</code> or <code>AWS:</code>. Values can have this prefix. If a\n                    tag value has <code>aws</code> as its prefix but the key does not, Forecast\n                    considers it to be a user tag and will count against the limit of 50 tags. Tags\n                    with only the key prefix of <code>aws</code> do not count against your tags per\n                    resource limit. You cannot edit or delete tag keys with this prefix.</p>\n            </li>\n         </ul>"}))
    CreateAutoPredictorRequest.add_member(:monitor_config, Smithy::Schema::Shapes::ShapeRef.new(shape: MonitorConfig, location_name: 'MonitorConfig', traits: {"smithy.api#documentation" => "<p>The configuration details for predictor monitoring. Provide a name for the monitor resource to enable predictor monitoring.</p>\n         <p>Predictor monitoring allows you to see how your predictor's performance changes over time.\n         For more information, see <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/predictor-monitoring.html\">Predictor Monitoring</a>.</p>"}))
    CreateAutoPredictorRequest.add_member(:time_alignment_boundary, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeAlignmentBoundary, location_name: 'TimeAlignmentBoundary', traits: {"smithy.api#documentation" => "<p>The time boundary Forecast uses to align and aggregate any data that doesn't align with your forecast frequency. Provide the unit of time and the time boundary as a key value pair. \n            For more information on specifying a time boundary, see <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/data-aggregation.html#specifying-time-boundary\">Specifying a Time Boundary</a>.\n            If you\n            don't provide a time boundary, Forecast uses a set of <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/data-aggregation.html#default-time-boundaries\">Default Time Boundaries</a>.</p>"}))
    CreateAutoPredictorRequest.type = Types::CreateAutoPredictorRequest
    CreateAutoPredictorResponse.add_member(:predictor_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'PredictorArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the predictor.</p>"}))
    CreateAutoPredictorResponse.type = Types::CreateAutoPredictorResponse
    CreateDatasetGroupRequest.add_member(:dataset_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'DatasetGroupName', traits: {"smithy.api#documentation" => "<p>A name for the dataset group.</p>", "smithy.api#required" => {}}))
    CreateDatasetGroupRequest.add_member(:domain, Smithy::Schema::Shapes::ShapeRef.new(shape: Domain, location_name: 'Domain', traits: {"smithy.api#documentation" => "<p>The domain associated with the dataset group. When you add a dataset to a dataset group,\n      this value and the value specified for the <code>Domain</code> parameter of the <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/API_CreateDataset.html\">CreateDataset</a>\n      operation must match.</p>\n         <p>The <code>Domain</code> and <code>DatasetType</code> that you choose determine the fields\n      that must be present in training data that you import to a dataset. For example, if you choose\n      the <code>RETAIL</code> domain and <code>TARGET_TIME_SERIES</code> as the\n        <code>DatasetType</code>, Amazon Forecast requires that <code>item_id</code>,\n        <code>timestamp</code>, and <code>demand</code> fields are present in your data. For more\n      information, see <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/howitworks-datasets-groups.html\">Dataset groups</a>.</p>", "smithy.api#required" => {}}))
    CreateDatasetGroupRequest.add_member(:dataset_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: ArnList, location_name: 'DatasetArns', traits: {"smithy.api#documentation" => "<p>An array of Amazon Resource Names (ARNs) of the datasets that you want to include in the\n      dataset group.</p>"}))
    CreateDatasetGroupRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The optional metadata that you apply to the dataset group to help you categorize and\n      organize them. Each tag consists of a key and an optional value, both of which you\n      define.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50.</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only one\n          value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources, remember that\n          other services may have restrictions on allowed characters. Generally allowed characters\n          are: letters, numbers, and spaces representable in UTF-8, and the following characters: +\n          - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase combination\n          of such as a prefix for keys as it is reserved for Amazon Web Services use. You cannot edit or delete tag\n          keys with this prefix. Values can have this prefix. If a tag value has <code>aws</code> as\n          its prefix but the key does not, then Forecast considers it to be a user tag and will\n          count against the limit of 50 tags. Tags with only the key prefix of <code>aws</code> do\n          not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    CreateDatasetGroupRequest.type = Types::CreateDatasetGroupRequest
    CreateDatasetGroupResponse.add_member(:dataset_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'DatasetGroupArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the dataset group.</p>"}))
    CreateDatasetGroupResponse.type = Types::CreateDatasetGroupResponse
    CreateDatasetImportJobRequest.add_member(:dataset_import_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'DatasetImportJobName', traits: {"smithy.api#documentation" => "<p>The name for the dataset import job. We recommend including the current timestamp in the\n      name, for example, <code>20190721DatasetImport</code>. This can help you avoid getting a\n        <code>ResourceAlreadyExistsException</code> exception.</p>", "smithy.api#required" => {}}))
    CreateDatasetImportJobRequest.add_member(:dataset_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'DatasetArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon Forecast dataset that you want to import data\n      to.</p>", "smithy.api#required" => {}}))
    CreateDatasetImportJobRequest.add_member(:data_source, Smithy::Schema::Shapes::ShapeRef.new(shape: DataSource, location_name: 'DataSource', traits: {"smithy.api#documentation" => "<p>The location of the training data to import and an Identity and Access Management (IAM) role that Amazon Forecast\n      can assume to access the data. The training data must be stored in an Amazon S3 bucket.</p>\n         <p>If encryption is used, <code>DataSource</code> must include an Key Management Service (KMS) key and the\n      IAM role must allow Amazon Forecast permission to access the key. The KMS key and IAM role must\n      match those specified in the <code>EncryptionConfig</code> parameter of the <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/API_CreateDataset.html\">CreateDataset</a>\n      operation.</p>", "smithy.api#required" => {}}))
    CreateDatasetImportJobRequest.add_member(:timestamp_format, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampFormat, location_name: 'TimestampFormat', traits: {"smithy.api#documentation" => "<p>The format of timestamps in the dataset. The format that you specify depends on the\n        <code>DataFrequency</code> specified when the dataset was created. The following formats are\n      supported</p>\n         <ul>\n            <li>\n               <p>\"yyyy-MM-dd\"</p>\n               <p>For the following data frequencies: Y, M, W, and D</p>\n            </li>\n            <li>\n               <p>\"yyyy-MM-dd HH:mm:ss\"</p>\n               <p>For the following data frequencies: H, 30min, 15min, and 1min; and optionally, for: Y,\n          M, W, and D</p>\n            </li>\n         </ul>\n         <p>If the format isn't specified, Amazon Forecast expects the format to be \"yyyy-MM-dd\n      HH:mm:ss\".</p>"}))
    CreateDatasetImportJobRequest.add_member(:time_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeZone, location_name: 'TimeZone', traits: {"smithy.api#documentation" => "<p>A single time zone for every item in your dataset. This option is ideal for datasets\n            with all timestamps within a single time zone, or if all timestamps are normalized to a\n            single time zone. </p>\n         <p>Refer to the <a href=\"http://joda-time.sourceforge.net/timezones.html\">Joda-Time\n                API</a> for a complete list of valid time zone names.</p>"}))
    CreateDatasetImportJobRequest.add_member(:use_geolocation_for_time_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: UseGeolocationForTimeZone, location_name: 'UseGeolocationForTimeZone', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Automatically derive time zone information from the geolocation attribute. This option\n            is ideal for datasets that contain timestamps in multiple time zones and those\n            timestamps are expressed in local time.</p>"}))
    CreateDatasetImportJobRequest.add_member(:geolocation_format, Smithy::Schema::Shapes::ShapeRef.new(shape: GeolocationFormat, location_name: 'GeolocationFormat', traits: {"smithy.api#documentation" => "<p>The format of the geolocation attribute. The geolocation attribute can be formatted in\n            one of two ways:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>LAT_LONG</code> - the latitude and longitude in decimal format (Example: 47.61_-122.33).</p>\n            </li>\n            <li>\n               <p>\n                  <code>CC_POSTALCODE</code> (US Only) - the country code (US), followed by the 5-digit ZIP code (Example: US_98121).</p>\n            </li>\n         </ul>"}))
    CreateDatasetImportJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The optional metadata that you apply to the dataset import job to help you categorize and\n      organize them. Each tag consists of a key and an optional value, both of which you\n      define.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50.</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only one\n          value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources, remember that\n          other services may have restrictions on allowed characters. Generally allowed characters\n          are: letters, numbers, and spaces representable in UTF-8, and the following characters: +\n          - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase combination\n          of such as a prefix for keys as it is reserved for Amazon Web Services use. You cannot edit or delete tag\n          keys with this prefix. Values can have this prefix. If a tag value has <code>aws</code> as\n          its prefix but the key does not, then Forecast considers it to be a user tag and will\n          count against the limit of 50 tags. Tags with only the key prefix of <code>aws</code> do\n          not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    CreateDatasetImportJobRequest.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: Format, location_name: 'Format', traits: {"smithy.api#documentation" => "<p>The format of the imported data, CSV or PARQUET. The default value is CSV.</p>"}))
    CreateDatasetImportJobRequest.add_member(:import_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: ImportMode, location_name: 'ImportMode', traits: {"smithy.api#documentation" => "<p>Specifies whether the dataset import job is a <code>FULL</code> or <code>INCREMENTAL</code> import. A <code>FULL</code> dataset import replaces all of the existing data with the newly imported data. An <code>INCREMENTAL</code> import appends the imported data to the existing data.</p>"}))
    CreateDatasetImportJobRequest.type = Types::CreateDatasetImportJobRequest
