    CreateExplainabilityRequest.add_member(:start_date_time, Smithy::Schema::Shapes::ShapeRef.new(shape: LocalDateTime, location_name: 'StartDateTime', traits: {"smithy.api#documentation" => "<p>If <code>TimePointGranularity</code> is set to <code>SPECIFIC</code>, define the first\n            point for the Explainability.</p>\n         <p>Use the following timestamp format: yyyy-MM-ddTHH:mm:ss (example:\n            2015-01-01T20:00:00)</p>"}))
