    CreateForecastRequest.add_member(:forecast_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'ForecastName', traits: {"smithy.api#documentation" => "<p>A name for the forecast.</p>", "smithy.api#required" => {}}))
    CreateForecastRequest.add_member(:predictor_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'PredictorArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the predictor to use to generate the forecast.</p>", "smithy.api#required" => {}}))
    CreateForecastRequest.add_member(:forecast_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastTypes, location_name: 'ForecastTypes', traits: {"smithy.api#documentation" => "<p>The quantiles at which probabilistic forecasts are generated. <b>You\n        can currently specify up to 5 quantiles per forecast</b>. Accepted values include\n        <code>0.01 to 0.99</code> (increments of .01 only) and <code>mean</code>. The mean forecast\n      is different from the median (0.50) when the distribution is not symmetric (for example, Beta\n      and Negative Binomial).\n      </p>\n         <p>The default quantiles are the quantiles you specified during predictor creation.\n      If you didn't specify quantiles, the default values are <code>[\"0.1\", \"0.5\", \"0.9\"]</code>.\n    </p>"}))
    CreateForecastRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The optional metadata that you apply to the forecast to help you categorize and organize\n      them. Each tag consists of a key and an optional value, both of which you define.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50.</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only one\n          value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources, remember that\n          other services may have restrictions on allowed characters. Generally allowed characters\n          are: letters, numbers, and spaces representable in UTF-8, and the following characters: +\n          - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase combination\n          of such as a prefix for keys as it is reserved for Amazon Web Services use. You cannot edit or delete tag\n          keys with this prefix. Values can have this prefix. If a tag value has <code>aws</code> as\n          its prefix but the key does not, then Forecast considers it to be a user tag and will\n          count against the limit of 50 tags. Tags with only the key prefix of <code>aws</code> do\n          not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    CreateForecastRequest.add_member(:time_series_selector, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeSeriesSelector, location_name: 'TimeSeriesSelector', traits: {"smithy.api#documentation" => "<p>Defines the set of time series that are used to create the forecasts in a <code>TimeSeriesIdentifiers</code> object.</p>\n         <p>The <code>TimeSeriesIdentifiers</code> object needs the following information:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DataSource</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Format</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Schema</code>\n               </p>\n            </li>\n         </ul>"}))
