    CreatePredictorBacktestExportJobRequest.add_member(:predictor_backtest_export_job_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'PredictorBacktestExportJobName', traits: {"smithy.api#documentation" => "<p>The name for the backtest export job.</p>", "smithy.api#required" => {}}))
    CreatePredictorBacktestExportJobRequest.add_member(:predictor_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'PredictorArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the predictor that you want to export.</p>", "smithy.api#required" => {}}))
    CreatePredictorBacktestExportJobRequest.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: DataDestination, location_name: 'Destination', traits: {"smithy.api#required" => {}}))
    CreatePredictorBacktestExportJobRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>Optional metadata to help you categorize and organize your backtests. Each tag\n            consists of a key and an optional value, both of which you define. Tag keys and values\n            are case sensitive.</p>\n         <p>The following restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>For each resource, each tag key must be unique and each tag key must have one\n                    value.</p>\n            </li>\n            <li>\n               <p>Maximum number of tags per resource: 50.</p>\n            </li>\n            <li>\n               <p>Maximum key length: 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length: 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Accepted characters: all letters and numbers, spaces representable in UTF-8,\n                    and + - = . _ : / @. If your tagging schema is used across other services and\n                    resources, the character restrictions of those services also apply. </p>\n            </li>\n            <li>\n               <p>Key prefixes cannot include any upper or lowercase combination of\n                        <code>aws:</code> or <code>AWS:</code>. Values can have this prefix. If a\n                    tag value has <code>aws</code> as its prefix but the key does not, Forecast\n                    considers it to be a user tag and will count against the limit of 50 tags. Tags\n                    with only the key prefix of <code>aws</code> do not count against your tags per\n                    resource limit. You cannot edit or delete tag keys with this prefix.</p>\n            </li>\n         </ul>"}))
    CreatePredictorBacktestExportJobRequest.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: Format, location_name: 'Format', traits: {"smithy.api#documentation" => "<p>The format of the exported data, CSV or PARQUET. The default value is CSV.</p>"}))
    CreatePredictorBacktestExportJobRequest.type = Types::CreatePredictorBacktestExportJobRequest
    CreatePredictorBacktestExportJobResponse.add_member(:predictor_backtest_export_job_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'PredictorBacktestExportJobArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the predictor backtest export job that you want to\n            export.</p>"}))
