    CreatePredictorRequest.add_member(:predictor_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'PredictorName', traits: {"smithy.api#documentation" => "<p>A name for the predictor.</p>", "smithy.api#required" => {}}))
    CreatePredictorRequest.add_member(:algorithm_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'AlgorithmArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the algorithm to use for model training. Required if\n        <code>PerformAutoML</code> is not set to <code>true</code>.</p>\n         <p class=\"title\">\n            <b>Supported algorithms:</b>\n         </p>\n         <ul>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/ARIMA</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/CNN-QR</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/Deep_AR_Plus</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/ETS</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/NPTS</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>arn:aws:forecast:::algorithm/Prophet</code>\n               </p>\n            </li>\n         </ul>"}))
    CreatePredictorRequest.add_member(:forecast_horizon, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ForecastHorizon', traits: {"smithy.api#documentation" => "<p>Specifies the number of time-steps that the model is trained to predict. The forecast\n      horizon is also called the prediction length.</p>\n         <p>For example, if you configure a dataset for daily data collection (using the\n        <code>DataFrequency</code> parameter of the <a>CreateDataset</a> operation) and\n      set the forecast horizon to 10, the model returns predictions for 10 days.</p>\n         <p>The maximum forecast horizon is the lesser of 500 time-steps or 1/3 of the\n      TARGET_TIME_SERIES dataset length.</p>", "smithy.api#required" => {}}))
    CreatePredictorRequest.add_member(:forecast_types, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastTypes, location_name: 'ForecastTypes', traits: {"smithy.api#documentation" => "<p>Specifies the forecast types used to train a predictor. You can specify up to five\n      forecast types. Forecast types can be quantiles from 0.01 to 0.99, by increments of 0.01 or\n      higher. You can also specify the mean forecast with <code>mean</code>. </p>\n         <p>The default value is <code>[\"0.10\", \"0.50\", \"0.9\"]</code>.</p>"}))
    CreatePredictorRequest.add_member(:perform_auto_ml, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PerformAutoML', traits: {"smithy.api#documentation" => "<p>Whether to perform AutoML. When Amazon Forecast performs AutoML, it evaluates the algorithms it\n      provides and chooses the best algorithm and configuration for your training dataset.</p>\n         <p>The default value is <code>false</code>. In this case, you are required to specify an\n      algorithm.</p>\n         <p>Set <code>PerformAutoML</code> to <code>true</code> to have Amazon Forecast perform AutoML. This\n      is a good option if you aren't sure which algorithm is suitable for your training data. In\n      this case, <code>PerformHPO</code> must be false.</p>"}))
    CreatePredictorRequest.add_member(:auto_ml_override_strategy, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoMLOverrideStrategy, location_name: 'AutoMLOverrideStrategy', traits: {"smithy.api#documentation" => "<note>\n            <p> The <code>LatencyOptimized</code> AutoML override strategy is only available in private beta.\n                Contact Amazon Web Services Support or your account manager to learn more about access privileges.\n            </p>\n         </note>\n         <p>Used to overide the default AutoML strategy, which is to optimize predictor accuracy.\n            To apply an AutoML strategy that minimizes training time, use\n                <code>LatencyOptimized</code>.</p>\n         <p>This parameter is only valid for predictors trained using AutoML.</p>"}))
    CreatePredictorRequest.add_member(:perform_hpo, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'PerformHPO', traits: {"smithy.api#documentation" => "<p>Whether to perform hyperparameter optimization (HPO). HPO finds optimal hyperparameter\n      values for your training data. The process of performing HPO is known as running a\n      hyperparameter tuning job.</p>\n         <p>The default value is <code>false</code>. In this case, Amazon Forecast uses default\n      hyperparameter values from the chosen algorithm.</p>\n         <p>To override the default values, set <code>PerformHPO</code> to <code>true</code> and,\n      optionally, supply the <a>HyperParameterTuningJobConfig</a> object. The tuning job\n      specifies a metric to optimize, which hyperparameters participate in tuning, and the valid\n      range for each tunable hyperparameter. In this case, you are required to specify an algorithm\n      and <code>PerformAutoML</code> must be false.</p>\n         <p>The following algorithms support HPO:</p>\n         <ul>\n            <li>\n               <p>DeepAR+</p>\n            </li>\n            <li>\n               <p>CNN-QR</p>\n            </li>\n         </ul>"}))
    CreatePredictorRequest.add_member(:training_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: TrainingParameters, location_name: 'TrainingParameters', traits: {"smithy.api#documentation" => "<p>The hyperparameters to override for model training. The hyperparameters that you can\n      override are listed in the individual algorithms. For the list of supported algorithms, see\n        <a>aws-forecast-choosing-recipes</a>.</p>"}))
    CreatePredictorRequest.add_member(:evaluation_parameters, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationParameters, location_name: 'EvaluationParameters', traits: {"smithy.api#documentation" => "<p>Used to override the default evaluation parameters of the specified algorithm. Amazon Forecast\n      evaluates a predictor by splitting a dataset into training data and testing data. The\n      evaluation parameters define how to perform the split and the number of iterations.</p>"}))
    CreatePredictorRequest.add_member(:hpo_config, Smithy::Schema::Shapes::ShapeRef.new(shape: HyperParameterTuningJobConfig, location_name: 'HPOConfig', traits: {"smithy.api#documentation" => "<p>Provides hyperparameter override values for the algorithm. If you don't provide this\n      parameter, Amazon Forecast uses default values. The individual algorithms specify which\n      hyperparameters support hyperparameter optimization (HPO). For more information, see <a>aws-forecast-choosing-recipes</a>.</p>\n         <p>If you included the <code>HPOConfig</code> object, you must set <code>PerformHPO</code> to\n      true.</p>"}))
    CreatePredictorRequest.add_member(:input_data_config, Smithy::Schema::Shapes::ShapeRef.new(shape: InputDataConfig, location_name: 'InputDataConfig', traits: {"smithy.api#documentation" => "<p>Describes the dataset group that contains the data to use to train the predictor.</p>", "smithy.api#required" => {}}))
    CreatePredictorRequest.add_member(:featurization_config, Smithy::Schema::Shapes::ShapeRef.new(shape: FeaturizationConfig, location_name: 'FeaturizationConfig', traits: {"smithy.api#documentation" => "<p>The featurization configuration.</p>", "smithy.api#required" => {}}))
    CreatePredictorRequest.add_member(:encryption_config, Smithy::Schema::Shapes::ShapeRef.new(shape: EncryptionConfig, location_name: 'EncryptionConfig', traits: {"smithy.api#documentation" => "<p>An Key Management Service (KMS) key and the Identity and Access Management (IAM) role that Amazon Forecast can assume to access\n      the key.</p>"}))
    CreatePredictorRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The optional metadata that you apply to the predictor to help you categorize and organize\n      them. Each tag consists of a key and an optional value, both of which you define.</p>\n         <p>The following basic restrictions apply to tags:</p>\n         <ul>\n            <li>\n               <p>Maximum number of tags per resource - 50.</p>\n            </li>\n            <li>\n               <p>For each resource, each tag key must be unique, and each tag key can have only one\n          value.</p>\n            </li>\n            <li>\n               <p>Maximum key length - 128 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>Maximum value length - 256 Unicode characters in UTF-8.</p>\n            </li>\n            <li>\n               <p>If your tagging schema is used across multiple services and resources, remember that\n          other services may have restrictions on allowed characters. Generally allowed characters\n          are: letters, numbers, and spaces representable in UTF-8, and the following characters: +\n          - = . _ : / @.</p>\n            </li>\n            <li>\n               <p>Tag keys and values are case sensitive.</p>\n            </li>\n            <li>\n               <p>Do not use <code>aws:</code>, <code>AWS:</code>, or any upper or lowercase combination\n          of such as a prefix for keys as it is reserved for Amazon Web Services use. You cannot edit or delete tag\n          keys with this prefix. Values can have this prefix. If a tag value has <code>aws</code> as\n          its prefix but the key does not, then Forecast considers it to be a user tag and will\n          count against the limit of 50 tags. Tags with only the key prefix of <code>aws</code> do\n          not count against your tags per resource limit.</p>\n            </li>\n         </ul>"}))
    CreatePredictorRequest.add_member(:optimization_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: OptimizationMetric, location_name: 'OptimizationMetric', traits: {"smithy.api#documentation" => "<p>The accuracy metric used to optimize the predictor.</p>"}))
    CreatePredictorRequest.type = Types::CreatePredictorRequest
    CreatePredictorResponse.add_member(:predictor_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'PredictorArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the predictor.</p>"}))
