    CreateWhatIfAnalysisRequest.add_member(:what_if_analysis_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'WhatIfAnalysisName', traits: {"smithy.api#documentation" => "<p>The name of the what-if analysis. Each name must be unique.</p>", "smithy.api#required" => {}}))
    CreateWhatIfAnalysisRequest.add_member(:forecast_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'ForecastArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the baseline forecast.</p>", "smithy.api#required" => {}}))
    CreateWhatIfAnalysisRequest.add_member(:time_series_selector, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeSeriesSelector, location_name: 'TimeSeriesSelector', traits: {"smithy.api#documentation" => "<p>Defines the set of time series that are used in the what-if analysis with a <code>TimeSeriesIdentifiers</code>\n      object. What-if analyses are performed only for the time series in this object.</p>\n         <p>The <code>TimeSeriesIdentifiers</code> object needs the following information:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>DataSource</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Format</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Schema</code>\n               </p>\n            </li>\n         </ul>"}))
    CreateWhatIfAnalysisRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/tagging-forecast-resources.html\">tags</a> to apply to the what if forecast.</p>"}))
    CreateWhatIfAnalysisRequest.type = Types::CreateWhatIfAnalysisRequest
    CreateWhatIfAnalysisResponse.add_member(:what_if_analysis_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'WhatIfAnalysisArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the what-if analysis.</p>"}))
    CreateWhatIfAnalysisResponse.type = Types::CreateWhatIfAnalysisResponse
    CreateWhatIfForecastExportRequest.add_member(:what_if_forecast_export_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'WhatIfForecastExportName', traits: {"smithy.api#documentation" => "<p>The name of the what-if forecast to export.</p>", "smithy.api#required" => {}}))
    CreateWhatIfForecastExportRequest.add_member(:what_if_forecast_arns, Smithy::Schema::Shapes::ShapeRef.new(shape: WhatIfForecastArnListForExport, location_name: 'WhatIfForecastArns', traits: {"smithy.api#documentation" => "<p>The list of what-if forecast Amazon Resource Names (ARNs) to export.</p>", "smithy.api#required" => {}}))
    CreateWhatIfForecastExportRequest.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: DataDestination, location_name: 'Destination', traits: {"smithy.api#documentation" => "<p>The location where you want to save the forecast and an Identity and Access Management (IAM) role that\n      Amazon Forecast can assume to access the location. The forecast must be exported to an Amazon S3\n      bucket.</p>\n         <p>If encryption is used, <code>Destination</code> must include an Key Management Service (KMS) key. The\n      IAM role must allow Amazon Forecast permission to access the key.</p>", "smithy.api#required" => {}}))
    CreateWhatIfForecastExportRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/tagging-forecast-resources.html\">tags</a> to apply to the what if forecast.</p>"}))
    CreateWhatIfForecastExportRequest.add_member(:format, Smithy::Schema::Shapes::ShapeRef.new(shape: Format, location_name: 'Format', traits: {"smithy.api#documentation" => "<p>The format of the exported data, CSV or PARQUET.</p>"}))
