    CreateWhatIfForecastExportResponse.add_member(:what_if_forecast_export_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: LongArn, location_name: 'WhatIfForecastExportArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the what-if forecast.</p>"}))
    CreateWhatIfForecastExportResponse.type = Types::CreateWhatIfForecastExportResponse
    CreateWhatIfForecastRequest.add_member(:what_if_forecast_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'WhatIfForecastName', traits: {"smithy.api#documentation" => "<p>The name of the what-if forecast. Names must be unique within each what-if analysis.</p>", "smithy.api#required" => {}}))
    CreateWhatIfForecastRequest.add_member(:what_if_analysis_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'WhatIfAnalysisArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the what-if analysis.</p>", "smithy.api#required" => {}}))
    CreateWhatIfForecastRequest.add_member(:time_series_transformations, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeSeriesTransformations, location_name: 'TimeSeriesTransformations', traits: {"smithy.api#documentation" => "<p>The transformations that are applied to the baseline time series. Each transformation contains an action and a set of conditions. An action is applied only when all conditions are met. If no conditions are provided, the action is applied to all items.</p>"}))
    CreateWhatIfForecastRequest.add_member(:time_series_replacements_data_source, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeSeriesReplacementsDataSource, location_name: 'TimeSeriesReplacementsDataSource', traits: {"smithy.api#documentation" => "<p>The replacement time series dataset, which contains the rows that you want to change in the related time\n      series dataset. A replacement time series does not need to contain all rows that are in the baseline related time\n      series. Include only the rows (measure-dimension combinations) that you want to include in the what-if\n      forecast.</p>\n         <p>This dataset is merged with the\n      original time series to create a transformed dataset that is used for the what-if analysis.</p>\n         <p>This dataset should contain the items to modify (such as item_id or workforce_type), any relevant dimensions, the timestamp column, and at least one of the related time series columns. This file should not contain duplicate timestamps for the same time series.</p>\n         <p>Timestamps and item_ids not included in this dataset are not included in the what-if analysis. </p>"}))
    CreateWhatIfForecastRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>A list of <a href=\"https://docs.aws.amazon.com/forecast/latest/dg/tagging-forecast-resources.html\">tags</a> to apply to the what if forecast.</p>"}))
    CreateWhatIfForecastRequest.type = Types::CreateWhatIfForecastRequest
