    CreateWhatIfForecastResponse.type = Types::CreateWhatIfForecastResponse
    DataConfig.add_member(:dataset_group_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: Arn, location_name: 'DatasetGroupArn', traits: {"smithy.api#documentation" => "<p>The ARN of the dataset group used to train the predictor.</p>", "smithy.api#required" => {}}))
    DataConfig.add_member(:attribute_configs, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeConfigs, location_name: 'AttributeConfigs', traits: {"smithy.api#documentation" => "<p>Aggregation and filling options for attributes in your dataset group.</p>"}))
    DataConfig.add_member(:additional_datasets, Smithy::Schema::Shapes::ShapeRef.new(shape: AdditionalDatasets, location_name: 'AdditionalDatasets', traits: {"smithy.api#documentation" => "<p>Additional built-in datasets like Holidays and the Weather Index.</p>"}))
    DataConfig.type = Types::DataConfig
    DataDestination.add_member(:s3_config, Smithy::Schema::Shapes::ShapeRef.new(shape: S3Config, location_name: 'S3Config', traits: {"smithy.api#documentation" => "<p>The path to an Amazon Simple Storage Service (Amazon S3) bucket along with the credentials to access the\n      bucket.</p>", "smithy.api#required" => {}}))
    DataDestination.type = Types::DataDestination
