    Featurization.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: Name, location_name: 'AttributeName', traits: {"smithy.api#documentation" => "<p>The name of the schema attribute that specifies the data field to be featurized. Amazon\n      Forecast supports the target field of the <code>TARGET_TIME_SERIES</code> and the\n        <code>RELATED_TIME_SERIES</code> datasets. For example, for the <code>RETAIL</code> domain,\n      the target is <code>demand</code>, and for the <code>CUSTOM</code> domain, the target is\n        <code>target_value</code>. For more information, see <a>howitworks-missing-values</a>.</p>", "smithy.api#required" => {}}))
    Featurization.add_member(:featurization_pipeline, Smithy::Schema::Shapes::ShapeRef.new(shape: FeaturizationPipeline, location_name: 'FeaturizationPipeline', traits: {"smithy.api#documentation" => "<p>An array of one <code>FeaturizationMethod</code> object that specifies the feature\n      transformation method.</p>"}))
    Featurization.type = Types::Featurization
    FeaturizationConfig.add_member(:forecast_frequency, Smithy::Schema::Shapes::ShapeRef.new(shape: Frequency, location_name: 'ForecastFrequency', traits: {"smithy.api#documentation" => "<p>The frequency of predictions in a forecast.</p>\n         <p>Valid intervals are an integer followed by Y (Year), M (Month), W (Week), D (Day), H (Hour), and min (Minute). For example,\n      \"1D\" indicates every day and \"15min\" indicates every 15 minutes. You cannot specify a value that would overlap with the next larger frequency. That means, for example, you cannot specify a frequency of 60 minutes, because that is equivalent to 1 hour. The valid values for each frequency are the following:</p>\n         <ul>\n            <li>\n               <p>Minute - 1-59</p>\n            </li>\n            <li>\n               <p>Hour - 1-23</p>\n            </li>\n            <li>\n               <p>Day - 1-6</p>\n            </li>\n            <li>\n               <p>Week - 1-4</p>\n            </li>\n            <li>\n               <p>Month - 1-11</p>\n            </li>\n            <li>\n               <p>Year - 1</p>\n            </li>\n         </ul>\n         <p>Thus, if you want every other week forecasts, specify \"2W\". Or, if you want quarterly forecasts, you specify \"3M\".</p>\n         <p>The frequency must be greater than or equal to the TARGET_TIME_SERIES dataset\n      frequency.</p>\n         <p>When a RELATED_TIME_SERIES dataset is provided, the frequency must be equal to the\n      TARGET_TIME_SERIES dataset frequency.</p>", "smithy.api#required" => {}}))
    FeaturizationConfig.add_member(:forecast_dimensions, Smithy::Schema::Shapes::ShapeRef.new(shape: ForecastDimensions, location_name: 'ForecastDimensions', traits: {"smithy.api#documentation" => "<p>An array of dimension (field) names that specify how to group the generated\n      forecast.</p>\n         <p>For example, suppose that you are generating a forecast for item sales across all of your\n      stores, and your dataset contains a <code>store_id</code> field. If you want the sales\n      forecast for each item by store, you would specify <code>store_id</code> as the\n      dimension.</p>\n         <p>All forecast dimensions specified in the <code>TARGET_TIME_SERIES</code> dataset don't\n      need to be specified in the <code>CreatePredictor</code> request. All forecast dimensions\n      specified in the <code>RELATED_TIME_SERIES</code> dataset must be specified in the\n        <code>CreatePredictor</code> request.</p>"}))
    FeaturizationConfig.add_member(:featurizations, Smithy::Schema::Shapes::ShapeRef.new(shape: Featurizations, location_name: 'Featurizations', traits: {"smithy.api#documentation" => "<p>An array of featurization (transformation) information for the fields of a dataset.</p>"}))
